public long modPow(long base, long exp, long m) {
    if (m == 1) return 0;
    long result = 1;
    base %= m;
    while (exp > 0) {
        if ((exp & 1) == 1) {
            result = (result * base) % m;
        }
        base = (base * base) % m;
        exp >>= 1;
    }
    return result;
}

