def mod_pow(self, base: int, exp: int, m: int) -> int:
    if m == 1:
        return 0
    result = 1
    base %= m
    while exp > 0:
        if exp & 1:
            result = (result * base) % m
        base = (base * base) % m
        exp >>= 1
    return result

